insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 0, '在传统数据库领域中，过去最常用的4种数据模型不包括以下哪一项？', '层次模型', '面向过程模型', '网状模型', '关系模型', 'B', 'A、C、D选项错误，B选项正确。资料指出，过去数据库领域中最常用的数据模型有4种：层次模型、网状模型、关系模型和面向对象模型 。其中并没有“面向过程模型”。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 1, '为了满足互联网对数据扩展、读写速度、支撑容量等要求，产生了一种区别于传统关系型数据库的新一代产品，它的总称是？', 'SDE', 'DBMS', 'NoSQL', 'SQL', 'C', 'A、B、D选项错误，C选项正确。随着多源异构大数据的产生，传统关系型数据库无法满足新需求，因此产生了一种全新的非关系型数据库产品，总称为NoSQL（意即“不仅仅是SQL”） 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 2, '与一般数据库相比，空间数据库具有多个显著特点。以下哪一项不属于这些特点？', '数据量特别大', '数据结构复杂', '数据关系简单单一', '数据应用广泛', 'C', 'A、B、D选项均属于空间数据库的特点，C选项错误。空间数据库不仅有大量的空间信息和属性数据，还需要定义多种复杂的空间关系（如拓扑关系）和逻辑关系，因此数据关系是“多样”且“复杂”的，而非简单单一 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 3, '在空间数据库设计的内容中，决定河流是建模为线要素还是面要素、以栅格还是矢量形式表达，属于以下哪个设计阶段？', '确定数据实体属性与空间结构', '实现丰富的地理实体行为', '选择数据模型与划分地理实体', '属性关系及完整性约束', 'C', 'A、B、D选项错误，C选项正确。资料明确指出，“选择数据模型与划分地理实体”是空间数据库设计的初级阶段，在此阶段需要决定地理实体是以矢量（点、线、面）还是栅格形式进行表达 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 4, '在空间数据库设计中，规定河流的平均宽度不可能是负值，这属于数据库设计中的哪一项内容？', '拓扑关系设计', '地理实体行为设计', '属性关系设计', '完整性约束设计', 'D', 'A、B、C选项错误，D选项正确。完整性约束是指某个属性字段值的可取值范围，例如河流宽度不能是负值或规定河流的等级。这种约束可以最大程度上避免出现异常值 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 5, '空间数据的一条记录（如一条弧段的坐标）的长度是不可限定的，且可能嵌套多个对象。这体现了空间数据的什么特征？', '空间坐标特征', '非结构化特征', '空间关系特征', '多尺度特征', 'B', 'A、C、D选项错误，B选项正确。通用关系数据库要求记录是定长的（结构化），但空间数据项是变长的（如多对坐标）且允许嵌套，这被称为空间数据的“非结构化特征” 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 6, '在组织空间数据时，将同一地理范围内众多地理现象按数据类型（如矢量、栅格）、专题内容等分别设定。这种组织方式称为？', '分层组织', '分块组织', '几何无缝组织', '多尺度组织', 'A', 'B、C、D选项错误，A选项正确。将空间数据根据分类、数据类型、专题内容、时间次序等进行设定，这是一种起源于地图制图的数据组织方式，称为分层组织 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 7, '在分块组织大范围空间数据时，其最主要的缺点是什么？', '会占用成倍的额外存储空间', '不利于对单一图块的数据进行存取', '割裂了跨多个分块的地理要素，给空间查询和分析造成障碍', '无法与分层组织方式同时使用', 'C', 'A、B、D选项错误，C选项正确。分块式组织可提高数据存取效率且可与分层同用，但其缺点是会割裂跨图块的要素（如长河、铁路），导致无法直接基于完整要素进行分析 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 8, '在视觉上消除了图幅缝隙，但在实际物理存储上要素间在接边处依然是断续的，这属于哪种无缝数据组织？', '几何无缝', '逻辑无缝', '物理无缝', '属性无缝', 'A', 'B、C、D选项错误，A选项正确。几何无缝通过几何接边处理让图形在视觉上连续，但物理存储依然是分块的，要素断续，无法进行完整的淹没分析等操作 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 9, '被分块割裂的地理要素，不仅在逻辑上共享相同的标识符（OID），且在物理上合并为同一个实体进行存储，这属于哪种组织方式？', '几何无缝', '逻辑无缝', '物理无缝', '拓扑无缝', 'C', 'A、B、D选项错误，C选项正确。物理无缝数据组织是将若干图块的空间数据进行物理接边整体合并，实现物理上和逻辑上的统一，有利于按地理实体操作大范围对象 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 10, '目前主要的多尺度空间数据库构建方式是哪一种？', '利用系统动态派生所有比例尺数据', '采用自动综合方法生成相邻比例尺数据', '按比例尺各个层级，事先分别构建多个比例尺数据库（静态方式）', '只保留一种微观比例尺，完全丢弃宏观比例尺', 'C', 'A、B、D选项错误，C选项正确。由于当前GIS自动综合技术仍是一个难题，动态方式和混合方式较难实现，因此事先单独建库的“静态方式”是当前多尺度构建的主要途径 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 11, '在属性数据组织方式中，既允许一个地物类有一个属性表，又允许多个地物类共用一个属性表（例如不同等级公路共用一个表）。这是哪种管理方式？', '与工作层对应的组织方式（如ArcGIS早期）', '与地物类对应的组织方式（如MGE）', '混合方式（如GeoStar）', '纯文件系统方式', 'C', 'A、B、D选项错误，C选项正确。这种吸收前两者优点的灵活设计被称为“混合方式”，代表软件如 GeoStar，它使得属性相同或相近的要素可以共用属性表，方便查询与分析 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 12, '早期传统的GIS软件（如ArcInfo）在管理空间数据时，采用的是什么主要模式？', '文件与关系数据库混合管理', '全关系型数据库管理', '对象-关系数据库管理', 'NoSQL数据库管理', 'A', 'B、C、D选项错误，A选项正确。由于早期关系数据库难以管理非结构化空间数据，传统GIS常采用文件管理图形数据、商用关系数据库管理属性数据的“混合管理”模式 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 13, '在全关系型数据库管理模式下，为了避免大量的关系表连接操作，通常将图形的变长坐标数据处理成什么类型的字段存入关系数据库中？', '整型 (Integer)', '字符串 (Varchar)', '二进制块 (BLOB)', '日期型 (Date)', 'C', 'A、B、D选项错误，C选项正确。全关系型管理中，为了存储变长的空间几何数据，大多商用数据库引入了 Binary 二进制 Block（BLOB）等长字节段结构交由数据库管理系统进行存取 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 14, '以下关于“对象-关系数据库管理”空间数据的说法中，正确的是哪一项？', '完全通过文件系统来操纵数据，不使用数据库', '数据库厂商对关系数据库进行了扩展，提供操纵点、线、面等空间对象的 API 函数', '用户可以不受任何限制地自由定义所有空间数据的拓扑结构', '这种方式下读写效率比直接使用二进制块(BLOB)更慢', 'B', 'A、C、D选项错误，B选项正确。对象-关系数据库由商用软件商进行了模块扩展，效率比BLOB高，但用户必须服从其预定义的空间对象结构，不能任意定义自己的拓扑结构 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 15, '当采用“文件+数据库管理方式”来管理栅格影像数据时，关系数据库中实际存储的是什么内容？', '完整的栅格影像二进制像素流', '所有地图矢量的拓扑坐标点', '影像的ID、文件名称、存储路径等索引和元数据信息', '时空大数据的分布式计算代码', 'C', 'A、B、D选项错误，C选项正确。在“文件+数据库”模式中，真正的影像数据仍按文件存储，数据库只负责管理其文件名称、路径等索引标识，从而提升检索效率 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 16, '为了解决时空大数据在存储效率与数据融合方面的问题，当前主要采用何种技术手段对海量数据进行存储管理？', '单机文件系统存储', '技术成熟的分布式存储方式', '人工分发光盘存储', '全局几何无缝单表存储', 'B', 'A、C、D选项错误，B选项正确。时空大数据具有多源异构、海量、实时等特征，目前主要通过技术成熟的“分布式存储方式”进行数据管理，以提升存取灵活性和分析扩展性 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 17, '关于空间数据库引擎（SDE）的两大流派，下列描述不正确的是哪一项？', 'ArcSDE 属于“中间件”方式的空间数据库引擎', 'Oracle Spatial 属于在数据库核心上做出扩展的“嵌入式”引擎', '早期 Oracle Spatial 仅实现简单要素的存储，不支持复杂拓扑关系', 'ArcSDE 和 Oracle Spatial 在架构和功能上没有任何区别', 'D', 'A、B、C选项均描述正确，D选项错误。两者具有本质区别：ArcSDE 是连接 GIS 与应用数据库的中间件；而 Oracle Spatial 是嵌入在数据库底层对数据模型直接进行的扩展 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 18, '空间索引是一种辅助性的数据结构，其建立的主要目的是什么？', '为了使空间数据在显示时色彩更加丰富', '通过筛选排除无关空间对象，从而提高空间数据检索和操作的效率', '自动纠正空间坐标系中的拓扑错误', '将矢量数据强制转换为栅格影像数据', 'B', 'A、C、D选项错误，B选项正确。因为空间数据量极大，空间索引介入空间操作与对象之间，能快速剔除无关对象，从而极大提升数据库和GIS的整体查询和访问性能 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 19, '在格网空间索引算法中，通常将覆盖区域划分为格网，并对格网进行编码。这种编码最常使用的是哪种编码？', '莫尔斯电码 (Morse code)', '统一资源标识符 (URI)', '十进制 Morton 码或 Peano 码', 'UTF-8 编码', 'C', 'A、B、D选项错误，C选项正确。在格网索引和线性四叉树索引中，为了建立线性表，通常将格网按照 Morton 码（又称 Peano 码）进行编码 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 20, 'R树和R+树空间索引算法是基于空间实体的哪一项特征来构建虚拟矩形的？', '实体的外接矩形 (Bounding Rectangle)', '实体的顶点数量 (Vertex count)', '实体的中心点 (Centroid)', '实体的面积大小 (Area size)', 'A', 'B、C、D选项错误，A选项正确。R树与R+树均利用空间实体的最大最小范围，即“外接矩形”进行空间重新组织，生成树状分层结构以加快检索效率 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 21, 'R树在构造时要求虚拟矩形尽量不要重叠，但在处理复杂空间对象时会有困难；为此产生了改进的R+树。R+树的主要特点是？', '彻底放弃使用外接矩形作为索引基础', '允许虚拟矩形可以相互重叠，并分割下层虚拟矩形或外接矩形', '要求所有外接矩形的面积必须严格相等', '仅支持点状实体的索引管理', 'B', 'A、C、D选项错误，B选项正确。为了解决重叠导致检索效率下降的问题，R+树允许虚拟矩形相互重叠并分割包含在其内的下层矩形，以保证检索时间相对稳定 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 22, 'SQL语言是数据库管理系统的核心，SQL的发展经历了多个版本，其中特别考虑扩展以“支持空间数据”的是哪一个版本？', 'SQL-86 (SQL-1)', 'SQL-89', 'SQL-92 (SQL-2)', 'SQL-99 (SQL-3)', 'D', 'A、B、C选项错误，D选项正确。从最初的SQL-86发展，直到SQL-99（也称SQL-3），此时规范才主要考虑了对通用SQL的扩展以支持空间数据处理 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 23, 'OGIS空间数据模型提出了对SQL进行二维空间ADT整合的规范。在规范定义的函数中，用于测试“两个几何体内部是否有一个非空的交集”的函数是？', 'Distance()', 'Envelope()', 'Overlap', 'IsEmpty()', 'C', 'A、B、D选项错误，C选项正确。根据OGIS标准拓扑运算表：Overlap 指示“如果两个几何体的内部有非空交集，则返回真”。（注：Intersect为几何体相交，Overlap更强调内部非空交集） 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 24, '下列哪种现象会显著影响关系数据库表分解后对空间面状实体的查询性能？', '使用 SQL 查询普通的文本字段', '将变长的空间坐标序列分解成定长记录，并在查询时进行大量的关系表连接操作', '属性数据采用二维表的方式组织', '引入空间数据库引擎（SDE）进行缓存', 'B', 'A、C、D选项错误，B选项正确。全关系管理在处理变长记录时若采用范式分解成定长表，会导致在读取面对象等复杂要素时需要执行海量费时的“表连接（Join）”操作，严重影响效率 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 25, '在构建多尺度空间数据库时，若由一个大比例尺数据库实时利用自动综合算法生成其他较小比例尺的数据，这被称为？', '静态方式', '动态方式', '混合方式', '文件存储方式', 'B', 'A、C、D选项错误，B选项正确。建库的三种途径中，由系统在大比例尺库基础上采用自动综合算法实时“动态地派生”其他尺度数据的方法，被称为动态方式 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 26, '随着时代发展，时空大数据的来源愈发广泛。以下选项中，通常不被视为典型时空大数据来源的是哪一项？', '包含时空位置的移动手机信令数据', '基于爬虫获取的携带位置信息的设计网络及日志数据', '车载导航系统的车辆追踪轨迹数据', '不包含任何地理坐标和时间标记的纯传统文学名著文本', 'D', 'A、B、C选项均属于资料中提及的时空大数据来源（基础测绘、遥感、导航定位、互联网及物联网数据），且均包含位置和时间属性。D选项无时空属性，不属于时空大数据 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 27, '在混合管理模式（文件管理图形、关系数据库管理属性）下，图形数据和属性数据通常通过什么关键元素进行联系？', 'MAC物理地址', '地图的颜色代码 (Color Code)', '目标标识或内部连接码 (OID)', 'SQL分析代码', 'C', 'A、B、D选项错误，C选项正确。在文件-关系混合管理中，文件系统的几何图形与关系库的属性数据是通过唯一的目标标识（OID）或内部连接码来建立联系与检索的 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 28, 'OGIS标准中的空间分析功能，若要返回“两个几何体与对方互不相交的部分”，应当使用的操作符是？', 'Distance', 'Intersection', 'ConvexHull', 'SysmmDiff', 'D', 'A、B、C选项错误，D选项正确。根据规范标准表，SysmmDiff (Symmetric Difference) 的功能就是返回两个几何体中与对方互不相交的部分 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-5', 29, '关于OGIS规范的扩展SQL（如SQL-99/SQL-3），目前资料指出了其存在一些局限性。以下哪一项属于其局限性？', '它不仅支持空间对象模型，也能完美支持所有场数据类型模型', '它十分重视并支持基于方位（如左、右、南、北）的度量操作', '它的操作过于关注基本拓扑和空间度量，而忽略了对基于方位、形状和可见性动态操作的支持', '它可以完全不借助系统就能自动补全受损数据', 'C', 'A、B、D选项错误，C选项正确。OGIS扩展面临的局限性包括：仅局限于对象模型（对场模型支持不够）、对简单连接查询局限、不支持方位方位谓词操作以及不支持动态/基于可见性的操作 。', datetime('now'));
